-- ── 1. R73 (a): visitors see sold and rented listings; a photo follows its listing's visibility ─────────────────────────────────────────────────
-- ALTER POLICY keeps the command and the roles. The photo policy's subquery runs under the caller's own RLS, so a photo is readable exactly when its listing is.
alter policy "Listings viewable by everyone" on public.listings using (status in ('active', 'sold', 'rented') or auth.uid() = user_id);
alter policy "Listing images viewable by everyone" on public.listing_images using (exists (select 1 from public.listings l where l.id = listing_id));

-- ── 2. R69 (b), (c): CHECKs, added NOT VALID (every new write is checked at once) and then validated (the preflight proved 0 breaking rows) ────────
-- title: 5 to 150 characters after btrim (src/modules/listings/validations/index.ts:7)
alter table public.listings add constraint listings_title_length_check check (char_length(btrim(title)) between 5 and 150) not valid;
-- description: null or at most 5000 characters (src/modules/listings/validations/index.ts:8)
alter table public.listings add constraint listings_description_length_check check (description is null or char_length(description) <= 5000) not valid;
-- price: above 0, no ceiling (src/modules/listings/validations/index.ts:9; C834)
alter table public.listings add constraint listings_price_positive_check check (price > 0) not valid;
-- price_old: null or above 0 (src/modules/listings/validations/index.ts:10)
alter table public.listings add constraint listings_price_old_positive_check check (price_old is null or price_old > 0) not valid;
-- lat (latitude): null or -90 to 90 (src/modules/listings/validations/index.ts:30)
alter table public.listings add constraint listings_lat_range_check check (lat is null or lat between -90 and 90) not valid;
-- lng (longitude): null or -180 to 180 (src/modules/listings/validations/index.ts:31)
alter table public.listings add constraint listings_lng_range_check check (lng is null or lng between -180 and 180) not valid;
-- url: starts with https://res.cloudinary.com/die7okukn/ (R69 (c), C833)
alter table public.listing_images add constraint listing_images_url_prefix_check check (starts_with(url, 'https://res.cloudinary.com/die7okukn/')) not valid;
alter table public.listings validate constraint listings_title_length_check;
alter table public.listings validate constraint listings_description_length_check;
alter table public.listings validate constraint listings_price_positive_check;
alter table public.listings validate constraint listings_price_old_positive_check;
alter table public.listings validate constraint listings_lat_range_check;
alter table public.listings validate constraint listings_lng_range_check;
alter table public.listing_images validate constraint listing_images_url_prefix_check;

-- ── 3. R69 (e): the three staff write policies of the avatars bucket (the bucket and its object stay) ──────────────────────────────────────────
drop policy "Admin/moderator delete avatars" on storage.objects;
drop policy "Admin/moderator update avatars" on storage.objects;
drop policy "Admin/moderator upload avatars" on storage.objects;

-- ── 4. R75 (c): the eight new moderator keys, allowed = true (today's behaviour; an administrator changes a switch later) ──────────────────────
insert into public.role_permissions (role, permission_key, allowed) values
  ('moderator', 'users.edit', true),
  ('moderator', 'users.verify', true),
  ('moderator', 'support.manage', true),
  ('moderator', 'inquiries.manage', true),
  ('moderator', 'catalog.manage', true),
  ('moderator', 'email_templates.manage', true),
  ('moderator', 'companies.manage', true),
  ('moderator', 'listings.moderate', true);

-- ── 5. R75 (f): the four policies of public.role_permissions (RLS stays on; with no policy and no grant a session reads and writes nothing) ──────
drop policy "role_permissions_admin_insert" on public.role_permissions;
drop policy "role_permissions_admin_select" on public.role_permissions;
drop policy "role_permissions_admin_update" on public.role_permissions;
drop policy "role_permissions_moderator_read" on public.role_permissions;

-- ── 5b. R86 (c) expand: the contact read for a caller the gateway has verified (service_role only) ───────────────────────────────────────────────
create function public.get_listing_owner_contact_as(p_caller uuid, listing_id_param uuid)
returns table(phone text, whatsapp text) language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if p_caller is null then raise exception 'unauthenticated' using errcode = '42501'; end if;
  -- the access predicate of caller_is_active(), for p_caller (its session part is the gateway's check)
  if not coalesce(
       (select u.deleted_at is null
           and (u.status = 'active' or (u.status = 'blocked' and u.suspended_until is not null and u.suspended_until <= now()))
        from public.users u where u.id = p_caller),
       false) then
    raise exception 'account_blocked' using errcode = '42501';
  end if;
  if not exists (select 1 from public.listings l join public.users u on u.id = l.user_id
                 where l.id = listing_id_param and l.status = 'active' and u.deleted_at is null) then
    return;
  end if;
  return query
    select u.phone, u.whatsapp from public.listings l join public.users u on u.id = l.user_id
    where l.id = listing_id_param and l.status = 'active' and u.deleted_at is null;
end $$;
revoke all on function public.get_listing_owner_contact_as(uuid, uuid) from public, anon, authenticated;
grant execute on function public.get_listing_owner_contact_as(uuid, uuid) to service_role;

-- ── 6. post-checks: what the statements above did, checked before the commit ────────────────────────────────────────────────────────────────────
do $post$
begin
  if not (exists (select 1 from pg_policies x where x.schemaname = 'public' and x.tablename = 'listings' and x.policyname = 'Listings viewable by everyone' and x.cmd = 'SELECT' and x.roles::text = '{public}' and x.permissive = 'PERMISSIVE' and x.qual like '%sold%' and x.qual like '%rented%' and x.qual like '%active%' and x.qual like '%user_id%') and exists (select 1 from pg_policies x where x.schemaname = 'public' and x.tablename = 'listing_images' and x.policyname = 'Listing images viewable by everyone' and x.cmd = 'SELECT' and x.roles::text = '{public}' and x.permissive = 'PERMISSIVE' and x.qual like '%listings%' and x.qual like '%listing_id%')) then
    raise exception 'post-check failed: a read policy is not as v8a wrote it';
  end if;
  if not (not exists (select 1 from pg_policies x where x.schemaname = 'storage' and x.tablename = 'objects' and x.policyname = 'Admin/moderator delete avatars') and not exists (select 1 from pg_policies x where x.schemaname = 'storage' and x.tablename = 'objects' and x.policyname = 'Admin/moderator update avatars') and not exists (select 1 from pg_policies x where x.schemaname = 'storage' and x.tablename = 'objects' and x.policyname = 'Admin/moderator upload avatars') and not exists (select 1 from pg_policies x where x.schemaname = 'public' and x.tablename = 'role_permissions' and x.policyname = 'role_permissions_admin_insert') and not exists (select 1 from pg_policies x where x.schemaname = 'public' and x.tablename = 'role_permissions' and x.policyname = 'role_permissions_admin_select') and not exists (select 1 from pg_policies x where x.schemaname = 'public' and x.tablename = 'role_permissions' and x.policyname = 'role_permissions_admin_update') and not exists (select 1 from pg_policies x where x.schemaname = 'public' and x.tablename = 'role_permissions' and x.policyname = 'role_permissions_moderator_read')) then
    raise exception 'post-check failed: a dropped policy still exists';
  end if;
  if not ((select count(*) from pg_constraint k where k.conname in ('listings_title_length_check', 'listings_description_length_check', 'listings_price_positive_check', 'listings_price_old_positive_check', 'listings_lat_range_check', 'listings_lng_range_check', 'listing_images_url_prefix_check') and k.conrelid in ('public.listings'::regclass, 'public.listing_images'::regclass) and k.contype = 'c' and k.convalidated) = 7) then
    raise exception 'post-check failed: a new constraint is missing or not validated';
  end if;
  if not ((select count(*) from public.role_permissions r where r.role = 'moderator' and r.allowed and r.permission_key in ('users.edit', 'users.verify', 'support.manage', 'inquiries.manage', 'catalog.manage', 'email_templates.manage', 'companies.manage', 'listings.moderate')) = 8 and (select count(*) from public.role_permissions r where r.permission_key in ('users.edit', 'users.verify', 'support.manage', 'inquiries.manage', 'catalog.manage', 'email_templates.manage', 'companies.manage', 'listings.moderate')) = 8) then
    raise exception 'post-check failed: the eight seeded rows are not as v8a wrote them';
  end if;
  if not (exists (select 1 from pg_proc p where p.oid = to_regprocedure('public.get_listing_owner_contact_as(uuid, uuid)') and p.prosecdef and p.proconfig = array['search_path=public, pg_temp']::text[] and p.prorettype = 'record'::regtype and has_function_privilege('service_role', p.oid, 'execute') and not has_function_privilege('anon', p.oid, 'execute') and not has_function_privilege('authenticated', p.oid, 'execute') and not exists (select 1 from aclexplode(p.proacl) a where a.grantee = 0))) then
    raise exception 'post-check failed: the new function is not as v8a wrote it';
  end if;
  if not ((select md5(pg_get_functiondef(p.oid)) from pg_proc p where p.oid = to_regprocedure('public.get_listing_owner_contact(uuid)')) is not distinct from '848eed2288d877f4703c8d13e605327d' and (select p.proacl::text from pg_proc p where p.oid = to_regprocedure('public.get_listing_owner_contact(uuid)')) is not distinct from '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}') then
    raise exception 'post-check failed: public.get_listing_owner_contact(uuid) changed';
  end if;
end $post$;

notify pgrst, 'reload schema';
commit;
